<?php
namespace Pterodactyl\Http\Controllers\Admin;
use Illuminate\Http\Request; use Illuminate\Support\Facades\Crypt; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Schema; use Illuminate\Support\Str; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Nodexa\FlaxVpsClient;
class VpsHostingController extends Controller {
private function remoteId(array $s):string{return (string)($s['id']??$s['server_id']??$s['serverId']??$s['uuid']??$s['service_id']??'');}
private function detail(array $a,array $keys,$default=null){foreach($keys as $k)if(isset($a[$k])&&$a[$k]!==''&&$a[$k]!==null)return $a[$k];return $default;}
private function serverDetails(FlaxVpsClient $api,string $id,array $seed=[]):array{$info=[];$os=[];try{$info=$api->info($id);}catch(\Throwable $e){}try{$os=$api->os($id);}catch(\Throwable $e){}$all=array_merge($seed,$info,$os);$ip=$this->detail($all,['ip_address','ipAddress','ip','main_ip','mainIp','ipv4','address']);if(is_array($ip))$ip=$ip[0]??null;$hostname=$this->detail($all,['hostname','host_name','server_name','serverName','name']);$osId=$this->detail($all,['os_id','osId','operatingSystem','operating_system','template_id','templateId']);$osName=$this->detail($all,['os_name','osName','operatingSystemName','operating_system_name','template_name','templateName']);$status=$this->detail($all,['status','state','power_status','powerStatus'],'active');return ['ip_address'=>$ip?:null,'hostname'=>$hostname?:null,'os_id'=>$osId!==null?(string)$osId:null,'os_name'=>$osName?:null,'status'=>(string)$status,'raw'=>$all];}
public function index(){ $provider=Schema::hasTable('vps_providers')?DB::table('vps_providers')->first():null;$packages=Schema::hasColumn('billing_products','product_type')?DB::table('billing_products')->where('product_type','vps')->orderBy('sort_order')->get():collect();$services=Schema::hasTable('vps_services')?DB::table('vps_services')->orderByDesc('id')->limit(100)->get():collect();$users=DB::table('users')->select('id','username','email')->orderBy('username')->get();$remotePackages=[];$operatingSystems=[];$remoteServers=[];$discoveryError=null;if($provider){try{$api=new FlaxVpsClient($provider);$remotePackages=$api->discoverProducts();$operatingSystems=$api->discoverOperatingSystems();$remoteServers=$api->servers();foreach($remoteServers as &$rs){$rid=$this->remoteId($rs);if($rid!==''){$d=$this->serverDetails($api,$rid,$rs);$rs['_nodexa_id']=$rid;$rs['_nodexa_ip']=$d['ip_address'];$rs['_nodexa_hostname']=$d['hostname'];$rs['_nodexa_os_id']=$d['os_id'];$rs['_nodexa_os_name']=$d['os_name'];$rs['_nodexa_status']=$d['status'];}}unset($rs);}catch(\Throwable $e){$discoveryError=$e->getMessage();}}return view('admin.commerce.vps',compact('provider','packages','services','users','remotePackages','operatingSystems','remoteServers','discoveryError'));}
public function saveProvider(Request $r){$d=$r->validate(['endpoint'=>'required|url|max:255','api_key'=>'nullable|string|max:1000']);$old=DB::table('vps_providers')->first();$key=!empty($d['api_key'])?Crypt::encryptString($d['api_key']):($old->api_key??null);if(!$key)return back()->withErrors(['api_key'=>'API-nøgle er påkrævet første gang.']);$values=['name'=>'Flax Hosting','endpoint'=>rtrim($d['endpoint'],'/'),'api_key'=>$key,'active'=>true,'updated_at'=>now()];if($old)DB::table('vps_providers')->where('id',$old->id)->update($values);else DB::table('vps_providers')->insert($values+['created_at'=>now()]);return back()->with('success','Flax VPS API blev gemt.');}
public function test(){try{$api=new FlaxVpsClient();$servers=$api->servers();$products=$api->discoverProducts();$oses=$api->discoverOperatingSystems();return back()->with('success','Flax API virker: '.count($servers).' server(e), '.count($products).' VPS-pakke(r), '.count($oses).' OS fundet.');}catch(\Throwable $e){return back()->withErrors(['flax'=>$e->getMessage()]);}}
public function assign(Request $r){$d=$r->validate(['provider_server_id'=>'required|string|max:120','user_id'=>'required|integer|exists:users,id','product_id'=>'nullable|integer','hostname'=>'nullable|string|max:255','ip_address'=>'nullable|string|max:255','os_id'=>'nullable|string|max:100']);if(!Schema::hasTable('vps_services'))return back()->withErrors(['vps'=>'VPS service-tabellen findes ikke. Kør Nodexa updater først.']);$provider=DB::table('vps_providers')->where('active',true)->first()?:DB::table('vps_providers')->first();if(!$provider)return back()->withErrors(['vps'=>'Flax API skal konfigureres først.']);$productId=!empty($d['product_id'])?(int)$d['product_id']:(int)(DB::table('billing_products')->where('product_type','vps')->value('id')??0);if(!$productId)return back()->withErrors(['product_id'=>'Vælg en VPS-pakke.']);$details=[];try{$api=new FlaxVpsClient($provider);$seed=[];foreach($api->servers() as $remote){if($this->remoteId($remote)===(string)$d['provider_server_id']){$seed=$remote;break;}}$details=$this->serverDetails($api,(string)$d['provider_server_id'],$seed);}catch(\Throwable $e){return back()->withInput()->withErrors(['vps'=>'Kunne ikke hente VPS-data fra Flax: '.$e->getMessage()]);}$existing=DB::table('vps_services')->where('provider_server_id',$d['provider_server_id'])->first();$values=['user_id'=>(int)$d['user_id'],'product_id'=>$productId,'provider_id'=>$provider->id,'hostname'=>$details['hostname']?:($d['hostname']??null),'ip_address'=>$details['ip_address']?:($d['ip_address']??null),'os_id'=>$details['os_id']?:($d['os_id']??null),'status'=>$details['status']?:'active','meta'=>json_encode(['assigned_manually'=>true,'os_name'=>$details['os_name']??null,'synced_at'=>now()->toIso8601String()]),'updated_at'=>now()];if($existing){DB::table('vps_services')->where('id',$existing->id)->update($values);$id=$existing->id;}else{$id=DB::table('vps_services')->insertGetId($values+['provider_server_id'=>$d['provider_server_id'],'order_id'=>null,'created_at'=>now()]);}return back()->with('success','VPS #'.$id.' er tilknyttet kunden. IP, hostname, OS og status blev hentet fra Flax.');}
public function reassign(Request $r,$id){$d=$r->validate(['user_id'=>'required|integer|exists:users,id']);$service=DB::table('vps_services')->where('id',$id)->first();if(!$service)return back()->withErrors(['vps'=>'VPS-service blev ikke fundet.']);DB::table('vps_services')->where('id',$id)->update(['user_id'=>(int)$d['user_id'],'updated_at'=>now()]);return back()->with('success','VPS #'.$id.' er flyttet til den valgte kunde.');}
public function syncServices(){if(!Schema::hasTable('vps_services'))return back()->withErrors(['vps'=>'VPS service-tabellen findes ikke.']);try{$provider=DB::table('vps_providers')->where('active',true)->first()?:DB::table('vps_providers')->first();$api=new FlaxVpsClient($provider);$remote=$api->servers();$count=0;foreach($remote as $seed){$id=$this->remoteId($seed);if($id==='')continue;$service=DB::table('vps_services')->where('provider_server_id',$id)->first();if(!$service)continue;$d=$this->serverDetails($api,$id,$seed);$meta=json_decode((string)($service->meta??''),true)?:[];$meta['os_name']=$d['os_name']??($meta['os_name']??null);$meta['synced_at']=now()->toIso8601String();DB::table('vps_services')->where('id',$service->id)->update(['hostname'=>$d['hostname']?:$service->hostname,'ip_address'=>$d['ip_address']?:$service->ip_address,'os_id'=>$d['os_id']?:$service->os_id,'status'=>$d['status']?:$service->status,'meta'=>json_encode($meta),'updated_at'=>now()]);$count++;}return back()->with('success',$count.' tilknyttede VPS(er) blev opdateret med nuværende data fra Flax.');}catch(\Throwable $e){return back()->withErrors(['flax'=>$e->getMessage()]);}}
public function sync(){try{$api=new FlaxVpsClient();$remote=$api->discoverProducts();if(!$remote)return back()->withErrors(['flax'=>'Flax API returnerede ingen produktliste.']);$count=0;foreach($remote as $p){$id=(string)($p['id']??$p['product_id']??$p['productId']??$p['uuid']??'');if($id==='')continue;$name=(string)($p['name']??$p['title']??$p['product_name']??('Flax VPS '.$id));$price=(float)($p['price']??$p['monthly_price']??$p['cost']??0);$ram=(int)($p['memory_mb']??$p['ram_mb']??$p['memory']??0);if($ram>0&&$ram<128)$ram*=1024;$disk=(int)($p['disk_mb']??$p['storage_mb']??$p['disk']??0);if($disk>0&&$disk<1024)$disk*=1024;$cores=(int)($p['vcores']??$p['cores']??$p['cpu']??0);$os=$api->discoverOperatingSystems($id);$osid=(string)($p['default_os_id']??($os[0]['id']??$os[0]['value']??$os[0]['template_id']??''));$existing=DB::table('billing_products')->where('product_type','vps')->where('provider_product_id',$id)->first();$values=['name'=>$name,'description'=>(string)($p['description']??'VPS leveret via Flax Hosting'),'product_type'=>'vps','provider_product_id'=>$id,'default_os_id'=>$osid?:null,'vcores'=>$cores?:null,'memory_mb'=>$ram?:null,'disk_mb'=>$disk?:null,'price'=>$price,'currency'=>strtoupper((string)($p['currency']??'DKK')),'billing_cycle'=>'monthly','active'=>true,'provisioning'=>json_encode(['type'=>'vps','provider'=>'flax','product_id'=>$id,'os_id'=>$osid]),'updated_at'=>now()];if($existing)DB::table('billing_products')->where('id',$existing->id)->update($values);else{$base=Str::slug($name)?:'flax-vps';$slug=$base;$i=2;while(DB::table('billing_products')->where('slug',$slug)->exists())$slug=$base.'-'.$i++;DB::table('billing_products')->insert($values+['slug'=>$slug,'cpu_percent'=>null,'databases_limit'=>0,'backups_limit'=>0,'allocations_limit'=>1,'sort_order'=>$count,'created_at'=>now()]);}$count++;}return back()->with('success',$count.' VPS-pakke(r) blev synkroniseret automatisk fra Flax.');}catch(\Throwable $e){return back()->withErrors(['flax'=>$e->getMessage()]);}}
public function storePackage(Request $r){$d=$r->validate(['name'=>'required|string|max:120','description'=>'nullable|string|max:1000','provider_product_id'=>'required|string|max:100','default_os_id'=>'required|string|max:100','vcores'=>'nullable|integer|min:1|max:256','memory_mb'=>'required|integer|min:128','disk_mb'=>'required|integer|min:1024','price'=>'required|numeric|min:0','currency'=>'required|string|size:3']);$base=Str::slug($d['name'])?:'vps';$slug=$base;$i=2;while(DB::table('billing_products')->where('slug',$slug)->exists())$slug=$base.'-'.$i++;DB::table('billing_products')->insert(['name'=>$d['name'],'slug'=>$slug,'description'=>$d['description']??null,'product_type'=>'vps','provider_product_id'=>$d['provider_product_id'],'default_os_id'=>$d['default_os_id'],'vcores'=>$d['vcores']??null,'memory_mb'=>$d['memory_mb'],'disk_mb'=>$d['disk_mb'],'cpu_percent'=>null,'databases_limit'=>0,'backups_limit'=>0,'allocations_limit'=>1,'price'=>$d['price'],'currency'=>strtoupper($d['currency']),'billing_cycle'=>'monthly','active'=>true,'sort_order'=>0,'provisioning'=>json_encode(['type'=>'vps','provider'=>'flax','product_id'=>$d['provider_product_id'],'os_id'=>$d['default_os_id']]),'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','VPS-pakken blev oprettet.');}
}